mapper.select:

WHERE 1 = 1

    AND CITD.ID = #{dto.id}


    AND CITD.`NAME` = #{dto.name}


    AND CITD.`GROUPING` = #{dto.grouping}


    AND CITD.ICON_TREE_TYPE = #{dto.iconTreeType}

SELECT CITD.id, CITD.rec_ver, CITD.header_id, CITD.header_id AS PARENT_ID, CITD.name, CITD.`grouping`, CITD.order_num, CITD.remark, CITD.icon_tree_type FROM COMMON_ICON_TEMPLATE_DETAIL CITD WHERE 1 = 1
AND CITD.ID = #{dto.id}
AND CITD.`NAME` = #{dto.name}
AND CITD.`GROUPING` = #{dto.grouping}
AND CITD.ICON_TREE_TYPE = #{dto.iconTreeType}
